inputs = ['ga', 'hvc', 'ackyh', 'ug', 'ycdy']
outputs = ['ga', 'hvc', 'ackkzyh', 'ug', 'fdkzy']

print("Input -> Output:")
for i in range(len(inputs)):
    print(f"'{inputs[i]}' -> '{outputs[i]}'")

# Let's check what changes are needed
print("\nChanges needed:")
for i in range(len(inputs)):
    inp = inputs[i]
    out = outputs[i]
    print(f"'{inp}' -> '{out}': ", end="")

    # Simple approach: check character by character differences
    if inp == out:
        print("No change")
    else:
        # Look for patterns in longer strings
        if len(inp) != len(out):
            print(f"Length change: {len(inp)} -> {len(out)}")
        else:
            diff = []
            for j in range(min(len(inp), len(out))):
                if inp[j] != out[j]:
                    diff.append(f"{inp[j]}->{out[j]}")
            if diff:
                print(", ".join(diff))
            else:
                print("Character level changes")

